-- Table: hrm_attendance_period
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_attendance_period (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    period_code  VARCHAR(7) NOT NULL UNIQUE,
    start_date   DATE NOT NULL,
    end_date     DATE NOT NULL,
    status       VARCHAR(20) NOT NULL DEFAULT 'draft'
                 CHECK (status IN ('draft', 'open', 'closed')),
    notes        TEXT,
    created_by   BIGINT REFERENCES masterdata_user(id),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (start_date <= end_date)
);
